// runner.server.ts — advances one analytics sync run inside a time budget.
//
// A run covers [range_start, range_end] in 30-day chunks. Inside each chunk it
// fetches one step at a time (daily totals, then each breakdown), writes the
// rows, and saves (cursor_date, cursor_step) — so a run that yields at its
// time budget, loses its lease or crashes resumes exactly where it stopped.
//
// Failures:
//   quota / upstream       retried with backoff (quota waits longer), up to max_attempts
//   token_expired          run fails; the connection is marked for reconnect
//   permission_denied /
//   not_found              run fails; the source is marked access_lost
//   config                 run fails (server setup)
//
// Store-agnostic: tested against store.memory.ts with a fake GoogleApi.
import "server-only";
import { addDays, daysInclusive, PRESET_DAYS, RANGE_PRESETS } from "@/lib/analytics/ranges";
import type { SyncErrorCode } from "@/lib/analytics/types";
import type { GoogleApi } from "../google/api.server";
import { GoogleApiError, userMessageFor } from "../google/errors";
import type {
  AnalyticsSyncStore,
  Ga4DimensionRow,
  GscDimensionRow,
  SourceRow,
  SyncRunRow,
} from "./store";

export const CHUNK_DAYS = 30;
export const LEASE_SECONDS = 150;
const MAX_CLAIMS = 200;

export const GA4_DIMENSIONS = [
  { key: "channel", api: "sessionDefaultChannelGroup", topN: 30 },
  { key: "source_medium", api: "sessionSourceMedium", topN: 50 },
  { key: "landing_page", api: "landingPagePlusQueryString", topN: 100 },
  { key: "country", api: "country", topN: 50 },
  { key: "device", api: "deviceCategory", topN: 10 },
] as const;

export const GSC_DIMENSIONS = [
  { key: "query", topN: 100 },
  { key: "page", topN: 100 },
  { key: "country", topN: 50 },
  { key: "device", topN: 10 },
] as const;

const GA4_TOTAL_METRICS = [
  "sessions",
  "totalUsers",
  "newUsers",
  "engagedSessions",
  "screenPageViews",
  "keyEvents",
  "averageSessionDuration",
  "bounceRate",
];
const GA4_DIM_METRICS = ["sessions", "totalUsers", "screenPageViews", "keyEvents"];

const GSC_PAGE_SIZE = 25_000;
const GSC_MAX_PAGES = 4;

export type SliceResult = "done" | "yield" | "retry" | "failed" | "lost_lease";

export type RunnerDeps = {
  store: AnalyticsSyncStore;
  apiFor: (connectionId: string, workspaceId: string) => GoogleApi;
  worker: string;
  /** Epoch ms; the slice stops starting new steps after this. */
  deadline: number;
  now?: () => number;
  /** Called once after a run succeeds (insights, cache warm-up). Errors are swallowed. */
  onSucceeded?: (run: SyncRunRow, source: SourceRow) => Promise<void>;
};

export class LeaseLostError extends Error {
  constructor() {
    super("lease lost");
    this.name = "LeaseLostError";
  }
}

const gaDate = (d: string) =>
  /^\d{8}$/.test(d) ? `${d.slice(0, 4)}-${d.slice(4, 6)}-${d.slice(6, 8)}` : d;
const clip = (v: string) => (v || "(not set)").slice(0, 600);

export function stepCount(kind: SourceRow["kind"]): number {
  return 1 + (kind === "ga4_property" ? GA4_DIMENSIONS.length : GSC_DIMENSIONS.length);
}

export function runProgress(
  run: Pick<SyncRunRow, "range_start" | "range_end" | "cursor_date" | "status">,
): number {
  if (run.status === "succeeded") return 1;
  const total = daysInclusive(run.range_start, run.range_end);
  const done = Math.max(0, daysInclusive(run.range_start, run.cursor_date) - 1);
  return Math.max(0, Math.min(1, done / total));
}

/** Keep the top N rows per day by the primary metric (index 0 of `metric`). */
function topPerDay<T extends { date: string }>(
  rows: T[],
  n: number,
  metric: (r: T) => number,
): T[] {
  const byDay = new Map<string, T[]>();
  for (const r of rows) {
    const list = byDay.get(r.date) ?? [];
    list.push(r);
    byDay.set(r.date, list);
  }
  const out: T[] = [];
  for (const list of byDay.values()) {
    list.sort((a, b) => metric(b) - metric(a));
    out.push(...list.slice(0, n));
  }
  return out;
}

/** Merge rows whose clipped value collides (PK safety). */
function mergeByKey<T extends { date: string; value: string }>(
  rows: T[],
  add: (a: T, b: T) => T,
): T[] {
  const map = new Map<string, T>();
  for (const r of rows) {
    const k = `${r.date}�${r.value}`;
    const prev = map.get(k);
    map.set(k, prev ? add(prev, r) : r);
  }
  return [...map.values()];
}

async function fetchStep(
  api: GoogleApi,
  source: SourceRow,
  step: number,
  from: string,
  to: string,
  store: AnalyticsSyncStore,
): Promise<number> {
  const base = { source_id: source.id, workspace_id: source.workspace_id };

  if (source.kind === "ga4_property") {
    if (step === 0) {
      const report = await api.runGa4Report(source.external_id, {
        startDate: from,
        endDate: to,
        dimensions: ["date"],
        metrics: GA4_TOTAL_METRICS,
        limit: 1000,
      });
      const rows = report.rows.map((r) => {
        const [sessions, users, newUsers, engaged, views, keyEvents, avgDuration, bounceRate] =
          r.metrics;
        return {
          ...base,
          date: gaDate(r.dimensions[0]),
          sessions: Math.round(sessions ?? 0),
          total_users: Math.round(users ?? 0),
          new_users: Math.round(newUsers ?? 0),
          engaged_sessions: Math.round(engaged ?? 0),
          screen_page_views: Math.round(views ?? 0),
          key_events: keyEvents ?? 0,
          session_duration_seconds: (avgDuration ?? 0) * (sessions ?? 0),
          bounced_sessions: (bounceRate ?? 0) * (sessions ?? 0),
        };
      });
      await store.upsertGa4Daily(rows);
      return rows.length;
    }
    const dim = GA4_DIMENSIONS[step - 1];
    const report = await api.runGa4Report(source.external_id, {
      startDate: from,
      endDate: to,
      dimensions: ["date", dim.api],
      metrics: GA4_DIM_METRICS,
      limit: 25_000,
      orderBySessionsDesc: true,
    });
    const rows: Ga4DimensionRow[] = mergeByKey(
      report.rows.map((r) => ({
        ...base,
        date: gaDate(r.dimensions[0]),
        dimension: dim.key,
        value: clip(r.dimensions[1]),
        sessions: Math.round(r.metrics[0] ?? 0),
        total_users: Math.round(r.metrics[1] ?? 0),
        screen_page_views: Math.round(r.metrics[2] ?? 0),
        key_events: r.metrics[3] ?? 0,
      })),
      (a, b) => ({
        ...a,
        sessions: a.sessions + b.sessions,
        total_users: a.total_users + b.total_users,
        screen_page_views: a.screen_page_views + b.screen_page_views,
        key_events: a.key_events + b.key_events,
      }),
    );
    const kept = topPerDay(rows, dim.topN, (r) => r.sessions);
    await store.replaceDimensionRows(
      "analytics_ga4_dimension_daily",
      source.id,
      dim.key,
      from,
      to,
      kept,
    );
    return kept.length;
  }

  // Search Console
  if (step === 0) {
    const rows = await api.queryGsc(source.external_id, {
      startDate: from,
      endDate: to,
      dimensions: ["date"],
      rowLimit: 1000,
    });
    const mapped = rows.map((r) => ({
      ...base,
      date: r.keys[0],
      clicks: Math.round(r.clicks),
      impressions: Math.round(r.impressions),
      position_weighted: r.position * r.impressions,
    }));
    await store.upsertGscDaily(mapped);
    return mapped.length;
  }
  const dim = GSC_DIMENSIONS[step - 1];
  const all: GscDimensionRow[] = [];
  for (let page = 0; page < GSC_MAX_PAGES; page++) {
    const rows = await api.queryGsc(source.external_id, {
      startDate: from,
      endDate: to,
      dimensions: ["date", dim.key],
      rowLimit: GSC_PAGE_SIZE,
      startRow: page * GSC_PAGE_SIZE,
    });
    for (const r of rows) {
      all.push({
        ...base,
        date: r.keys[0],
        dimension: dim.key,
        value: clip(r.keys[1] ?? ""),
        clicks: Math.round(r.clicks),
        impressions: Math.round(r.impressions),
        position_weighted: r.position * r.impressions,
      });
    }
    if (rows.length < GSC_PAGE_SIZE) break;
  }
  const merged = mergeByKey(all, (a, b) => ({
    ...a,
    clicks: a.clicks + b.clicks,
    impressions: a.impressions + b.impressions,
    position_weighted: a.position_weighted + b.position_weighted,
  }));
  const kept = topPerDay(merged, dim.topN, (r) => r.clicks * 1_000_000 + r.impressions);
  await store.replaceDimensionRows(
    "analytics_gsc_dimension_daily",
    source.id,
    dim.key,
    from,
    to,
    kept,
  );
  return kept.length;
}

/**
 * GA4 users are not additive across days. After the daily data is written,
 * cache the exact user totals for each preset window (current + previous)
 * ending on the run's last date.
 */
export async function cachePresetUserTotals(
  api: GoogleApi,
  source: SourceRow,
  lastDate: string,
  store: AnalyticsSyncStore,
): Promise<void> {
  if (source.kind !== "ga4_property") return;
  const windows: Array<{ from: string; to: string }> = [];
  for (const preset of RANGE_PRESETS) {
    const days = PRESET_DAYS[preset];
    const to = lastDate;
    const from = addDays(to, -(days - 1));
    windows.push({ from, to }, { from: addDays(from, -days), to: addDays(from, -1) });
  }
  const rows = [];
  for (const w of windows) {
    const report = await api.runGa4Report(source.external_id, {
      startDate: w.from,
      endDate: w.to,
      dimensions: [],
      metrics: ["totalUsers"],
      limit: 1,
    });
    rows.push({
      source_id: source.id,
      workspace_id: source.workspace_id,
      date_from: w.from,
      date_to: w.to,
      total_users: Math.round(report.rows[0]?.metrics[0] ?? 0),
    });
  }
  await store.upsertGa4PeriodTotals(rows);
}

function backoffMs(code: SyncErrorCode, failures: number, retryAfterSeconds?: number): number {
  const base = code === "quota" ? 5 * 60_000 : 30_000;
  const ms = Math.min(base * 2 ** Math.max(0, failures - 1), 6 * 3600_000);
  return Math.max(ms, (retryAfterSeconds ?? 0) * 1000);
}

/** Advance one claimed run until done, yield, retry or failure. */
export async function advanceRun(claimed: SyncRunRow, deps: RunnerDeps): Promise<SliceResult> {
  const now = deps.now ?? Date.now;
  const iso = (ms = now()) => new Date(ms).toISOString();
  let run = claimed;

  const update = async (patch: Parameters<AnalyticsSyncStore["updateRun"]>[2]) => {
    const ok = await deps.store.updateRun(run.id, deps.worker, patch);
    if (!ok) throw new LeaseLostError();
    run = { ...run, ...patch } as SyncRunRow;
  };

  const fail = async (code: SyncErrorCode, message: string): Promise<SliceResult> => {
    await update({
      status: "failed",
      error_code: code,
      error_message: message.slice(0, 500),
      completed_at: iso(),
      lease_until: null,
    });
    return "failed";
  };

  try {
    const source = await deps.store.getSource(run.source_id);
    if (!source || source.workspace_id !== run.workspace_id) {
      return await fail("not_found", "This property or site was removed from Mellox.");
    }
    const connection = await deps.store.getConnection(source.connection_id);
    if (
      !connection ||
      connection.workspace_id !== source.workspace_id ||
      connection.status === "revoked"
    ) {
      return await fail("token_expired", userMessageFor("token_expired"));
    }
    if (run.attempts > MAX_CLAIMS)
      return await fail("internal", "The sync took too many attempts.");

    const api = deps.apiFor(source.connection_id, source.workspace_id);
    const steps = stepCount(source.kind);

    while (run.cursor_date <= run.range_end) {
      if (now() >= deps.deadline) {
        // Hand the lease back so the next claim resumes right away.
        await update({ lease_until: iso(now() - 1000) });
        return "yield";
      }
      const chunkEnd =
        addDays(run.cursor_date, CHUNK_DAYS - 1) < run.range_end
          ? addDays(run.cursor_date, CHUNK_DAYS - 1)
          : run.range_end;
      const written = await fetchStep(
        api,
        source,
        run.cursor_step,
        run.cursor_date,
        chunkEnd,
        deps.store,
      );
      const nextStep = run.cursor_step + 1;
      await update(
        nextStep >= steps
          ? {
              cursor_step: 0,
              cursor_date: addDays(chunkEnd, 1),
              rows_written: run.rows_written + written,
              failures: 0,
              error_code: null,
              error_message: null,
            }
          : { cursor_step: nextStep, rows_written: run.rows_written + written },
      );
    }

    await cachePresetUserTotals(api, source, run.range_end, deps.store);

    const finishedAt = iso();
    await update({
      status: "succeeded",
      completed_at: finishedAt,
      lease_until: null,
      error_code: null,
      error_message: null,
    });
    const latestSynced =
      source.last_synced_date && source.last_synced_date > run.range_end
        ? source.last_synced_date
        : run.range_end;
    await deps.store.updateSource(source.id, {
      status: "active",
      last_error: null,
      last_synced_at: finishedAt,
      last_synced_date: latestSynced,
      ...(run.trigger === "initial" ? { backfill_completed_at: finishedAt } : {}),
    });
    if (deps.onSucceeded) {
      try {
        await deps.onSucceeded(run, { ...source, last_synced_date: latestSynced });
      } catch (e) {
        console.warn("[analytics] post-sync hook failed:", e instanceof Error ? e.message : e);
      }
    }
    return "done";
  } catch (e) {
    if (e instanceof LeaseLostError) return "lost_lease";
    if (e instanceof GoogleApiError) {
      const message = userMessageFor(e.code);
      if (e.retryable) {
        const failures = run.failures + 1;
        if (failures >= run.max_attempts) {
          await deps.store.updateSource(run.source_id, { last_error: message }).catch(() => {});
          return await fail(e.code, message).catch(() => "lost_lease" as const);
        }
        await update({
          failures,
          error_code: e.code,
          error_message: message,
          next_attempt_at: iso(now() + backoffMs(e.code, failures, e.opts.retryAfterSeconds)),
          lease_until: null,
        }).catch(() => {});
        return "retry";
      }
      if (e.code === "permission_denied" || e.code === "not_found") {
        await deps.store
          .updateSource(run.source_id, { status: "access_lost", last_error: message })
          .catch(() => {});
      }
      return await fail(e.code, e.code === "config" ? e.message : message).catch(
        () => "lost_lease" as const,
      );
    }
    console.error("[analytics] sync failed:", e instanceof Error ? e.message : e);
    return await fail("internal", userMessageFor("internal")).catch(() => "lost_lease" as const);
  }
}
